cssAppend.assets/brand-system.css:
/* Public readability refinement: preserve all existing colours and page grids. */
body[data-page] .site-shell {
  font-family: "Segoe UI", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  line-height: 1.65;
}
body[data-page] .site-shell :is(button, input, select, textarea) { font-family: inherit; }
body[data-page] main :is(.form-help, .project-evidence-note, .project-frame-label, .project-selected-filter, .project-filter-count, figcaption) {
  font-size: 14px;
  line-height: 1.6;
}
body[data-page] main :is(.section-head, .home-section-heading) h2 {
  font-size: clamp(28px, 2.6vw, 40px);
  line-height: 1.22;
  text-wrap: balance;
}
body[data-page] main :is(.card, .proof-card, .solution-card, .project-plan, .buyer-proof) { min-width: 0; }
body[data-page] main :is(.grid, .project-directory-grid) > :is(.card, .proof-card, .solution-card, .project-plan, .buyer-proof) {
  display: flex;
  flex-direction: column;
}
body[data-page] main :is(.grid, .project-directory-grid) > :is(.card, .proof-card, .solution-card, .project-plan, .buyer-proof) > :is(.button, .text-link):last-child {
  margin-top: auto;
  align-self: flex-start;
}
body[data-page] main :is(.card, .proof-card, .solution-card) > h3 { margin-block: 0 12px; }
body[data-page] main :is(.card, .proof-card, .solution-card) > p { line-height: 1.65; }
@media (max-width: 1180px) {
  body[data-page] .topbar .mobile-demo {
    max-width: 126px;
    font-size: 13px;
    line-height: 1.3;
    text-align: center;
    white-space: normal;
  }
  body[data-page] .topbar .brand-copy { min-width: 0; }
}
@media (max-width: 760px) {
  html:has(body[data-page] .mobile-contact-bar:not([hidden])) {
    scroll-padding-bottom: calc(108px + env(safe-area-inset-bottom, 0px));
  }
  body[data-page]:has(.mobile-contact-bar) {
    padding-bottom: calc(108px + env(safe-area-inset-bottom, 0px));
  }
  body[data-page] .mobile-contact-bar {
    padding: 12px max(12px, env(safe-area-inset-right, 0px)) calc(12px + env(safe-area-inset-bottom, 0px)) max(12px, env(safe-area-inset-left, 0px));
    align-items: stretch;
  }
  body[data-page] .mobile-contact-bar a {
    min-width: 0;
    min-height: 48px;
    padding: 8px;
    font-size: 14px;
    line-height: 1.4;
    text-align: center;
    white-space: normal;
  }
  body[data-page] main :is(a, button, summary, input, select, textarea) {
    scroll-margin-bottom: calc(108px + env(safe-area-inset-bottom, 0px));
  }
}

cssAppend.assets/home-focus.css:
/* Refine existing homepage type and spacing without moving sections or changing colour. */
body[data-page="home"] .home-work-heading h2 {
  font-size: clamp(28px, 2.5vw, 38px);
  line-height: 1.22;
  max-width: 25ch;
  text-wrap: balance;
}
body[data-page="home"] .home-work-heading > p { font-size: 16px; }
body[data-page="home"] #intl-crm-preview { padding-block: 8px; }
body[data-page="home"] #intl-crm-preview .intl-pipeline { padding: 8px 14px; }
body[data-page="home"] #intl-crm-preview .intl-pipeline-head { margin-bottom: 6px; }
body[data-page="home"] #intl-crm-preview .intl-pipeline-head h2 { font-size: clamp(23px, 1.8vw, 28px); }
body[data-page="home"] #intl-crm-preview .home-crm-steps { gap: 8px; margin-bottom: 6px; }
body[data-page="home"] #intl-crm-preview .home-crm-steps button { font-size: 14px; padding: 8px 4px; }
body[data-page="home"] #intl-crm-preview .home-crm-progress { font-size: 14px; line-height: 1.5; margin: 0 0 6px; }
body[data-page="home"] #intl-crm-preview .intl-board > .intl-lane > h3 { margin-bottom: 6px; font-size: 14px; }
body[data-page="home"] #intl-crm-preview .intl-lead { padding: 10px 12px; }
body[data-page="home"] #intl-crm-preview .intl-next span { font-size: 14px; margin-bottom: 4px; }
body[data-page="home"] #intl-crm-preview .intl-owner,
body[data-page="home"] #intl-crm-preview .intl-fiction { font-size: 14px; line-height: 1.5; margin-top: 8px; }
body[data-page="home"] #intl-crm-preview .intl-showcase-caption { padding-top: 8px; }
body[data-page="home"] #intl-crm-preview .intl-sample { font-size: 12px; line-height: 1.5; }
body[data-page="home"] #intl-crm-preview .intl-showcase-top .intl-eyebrow { font-size: 12px; }
body[data-page="home"] .home-work-card-copy { padding: 22px; gap: 10px; }
body[data-page="home"] .home-work-kind { font-size: 13px; line-height: 1.5; }
body[data-page="home"] .home-work-card-copy h3 { margin: 0; font-size: 24px; line-height: 1.3; }
body[data-page="home"] .home-work-card-copy p { margin: 0; font-size: 16px; line-height: 1.65; }
body[data-page="home"] .home-work-card-copy > a { padding-block: 8px; font-size: 14px; font-weight: 650; }
body[data-page="home"] .home-work-card-copy small { margin: 0; font-size: 14px; line-height: 1.6; min-height: 4.8em; }
body[data-page="home"] .home-hero-markets :is(.home-market-label, .home-market-context, .home-market-currency),
body[data-page="home"] main .home-assurance { font-size: 14px; line-height: 1.6; }
@media (max-width: 680px) {
  body[data-page="home"] #intl-crm-preview .intl-pipeline { padding: 8px 12px; }
  body[data-page="home"] .home-work-card-copy { padding: 20px; }
  body[data-page="home"] .home-work-card-copy small { min-height: 0; }
}
